import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas=document.querySelector('#game'),mini=document.querySelector('#minimap');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
const scene=new THREE.Scene();scene.background=new THREE.Color('#84c5d0');scene.fog=new THREE.FogExp2('#9ac9c4',.0025);
const camera=new THREE.PerspectiveCamera(62,innerWidth/innerHeight,.1,700);
scene.add(new THREE.HemisphereLight('#dcf4ff','#465b48',2.05));
const sun=new THREE.DirectionalLight('#ffe0b0',3.3);sun.position.set(-65,105,-35);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-115;sun.shadow.camera.right=115;sun.shadow.camera.top=115;sun.shadow.camera.bottom=-115;sun.shadow.bias=-.00015;scene.add(sun);
const mat=(color,roughness=.82,extra={})=>new THREE.MeshStandardMaterial({color,roughness,...extra});
const M={grass:mat('#7cae83'),road:mat('#454c4c'),roadLine:mat('#ead5a9'),sidewalk:mat('#d7c6a9'),water:mat('#3f9ca3',{roughness:.27}),sand:mat('#e6c594'),palm:mat('#775a43'),leaf:mat('#426b4c'),trunk:mat('#8d6949'),white:mat('#f3e8d2'),glass:mat('#76b6bd',{roughness:.23,metalness:.18}),black:mat('#18262a'),gold:mat('#d9a968')};
const world={objects:[],buildings:[],trees:[],vehicles:[],npcs:[],missionMarkers:[],projectiles:[]};
const boxGeo=new THREE.BoxGeometry(1,1,1),sphereGeo=new THREE.SphereGeometry(1,12,10),cylGeo=new THREE.CylinderGeometry(.5,.5,1,10);
function addBox(parent,position,size,material,opts={}){const m=new THREE.Mesh(boxGeo,material);m.position.set(...position);m.scale.set(...size);m.castShadow=opts.cast!==false;m.receiveShadow=true;parent.add(m);return m}
function addCyl(parent,pos,rTop,rBot,height,material,seg=9){const m=new THREE.Mesh(new THREE.CylinderGeometry(rTop,rBot,height,seg),material);m.position.set(...pos);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function seeded(seed){let s=seed>>>0;return()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296}}
const rand=seeded(4972);

function makeFacade(base,seed){const c=document.createElement('canvas');c.width=256;c.height=384;const x=c.getContext('2d');x.fillStyle=base;x.fillRect(0,0,c.width,c.height);x.fillStyle='rgba(25,36,37,.12)';x.fillRect(0,0,256,12);const colors=['#86c2bf','#edcb95','#4c777e','#f1e0bb','#6e9995'];for(let y=24;y<355;y+=49){for(let xx=17;xx<245;xx+=44){x.fillStyle='rgba(28,47,51,.27)';x.fillRect(xx-3,y-3,31,34);x.fillStyle=colors[(seed+Math.floor(xx/44)+Math.floor(y/49))%colors.length];x.fillRect(xx,y,25,27);x.fillStyle='rgba(255,244,208,.42)';x.fillRect(xx+2,y+2,3,23);x.fillStyle='#efe0c2';x.fillRect(xx-2,y+26,29,3)}}x.fillStyle='rgba(255,255,255,.13)';for(let y=2;y<384;y+=49)x.fillRect(0,y,256,3);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;t.wrapS=t.wrapT=THREE.RepeatWrapping;t.anisotropy=4;return t}
function building(x,z,w,d,h,style=0){const group=new THREE.Group();group.position.set(x,0,z);scene.add(group);const palette=style===0?['#f1d0a2','#f1e4c8','#f2a88f','#d9c4a0','#d3e2d5']:['#e6c398','#f2e3cc','#bdd6cf','#eac3a1'];const color=palette[Math.floor(rand()*palette.length)],tex=makeFacade(color,Math.floor(rand()*15));const wall=new THREE.MeshStandardMaterial({map:tex,color:'#ffffff',roughness:.84});addBox(group,[0,h/2,0],[w,h,d],wall);addBox(group,[0,h+.25,0],[w+.55,.5,d+.55],mat(style===0?'#ead6b1':'#d5c9b2'));addBox(group,[0,.24,0],[w+.7,.35,d+.7],mat('#d9bc91'));
 if(h>15&&style===0){addBox(group,[0,h+.75,0],[w*.45,.45,d*.45],mat('#eee0c2'));addCyl(group,[0,h+1.5,0],.09,.15,1.5,mat('#d8ad76'),8)}
 if(style===0){addBox(group,[0,3.8,d/2+.11],[w*.25,1.1,.12],mat(['#efb87a','#60a6a7','#de8078'][Math.floor(rand()*3)]));addBox(group,[0,3.17,d/2+.12],[w*.42,.16,.17],mat('#f4dfbb'))}
 world.buildings.push({x,z,w,d,h});return group}

// WORLD GENERATION
function buildWorld(){}

