// WORLD GENERATION
function palm(x,z,scale=1,swamp=false){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(scale);scene.add(g);const height=swamp?5.5:7;addCyl(g,[0,height/2,0],.2,.34,height,M.trunk,8);for(let i=0;i<8;i++){const a=i*Math.PI/4;const frond=new THREE.Group();frond.position.set(0,height*.91,0);frond.rotation.y=a;frond.rotation.z=-.66;g.add(frond);const leaf=new THREE.Mesh(new THREE.ConeGeometry(.52,3.8,5),mat(swamp?(i%2?'#527b55':'#456d50'):(i%2?'#427c54':'#5f9255')));leaf.rotation.z=-Math.PI/2;leaf.position.x=1.7;leaf.castShadow=true;frond.add(leaf);for(let j=0;j<4;j++){const blade=addBox(frond,[.7+j*.55,-.22-j*.12,((j%2)*2-1)*.18],[1.3,.09,.13],mat(swamp?'#5c8053':'#57905d'));blade.rotation.z=.27+j*.18}}
 if(swamp){const roots=mat('#725640');for(let i=0;i<4;i++){const a=i*Math.PI/2;const r=addCyl(g,[Math.sin(a)*.55,.55,Math.cos(a)*.55],.08,.22,1.3,roots,6);r.rotation.x=Math.cos(a)*-.48;r.rotation.z=Math.sin(a)*.48}}world.trees.push({x,z})}
function smallTree(x,z,scale=1){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(scale);scene.add(g);addCyl(g,[0,1.55,0],.15,.24,3.1,M.trunk,7);for(let i=0;i<3;i++){const crown=new THREE.Mesh(new THREE.SphereGeometry(1.05,9,7),mat(['#56855a','#68965c','#477b55'][i]));crown.position.set((rand()-.5)*.8,2.8+rand()*.65,(rand()-.5)*.8);crown.castShadow=true;g.add(crown)}}
function streetLight(x,z){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);addCyl(g,[0,2.8,0],.065,.09,5.6,mat('#495351'),7);addBox(g,[.4,5.45,0],[.9,.1,.1],mat('#495351'));const lamp=new THREE.Mesh(new THREE.SphereGeometry(.14,8,7),new THREE.MeshBasicMaterial({color:'#fff0c1'}));lamp.position.set(.82,5.37,0);g.add(lamp)}
function buildWorld(){
 addBox(scene,[0,-.8,0],[500,1,500],M.grass,{cast:false});
 // Bayside water and sandy edges divide city from the mangrove wilds.
 const water=new THREE.Mesh(new THREE.PlaneGeometry(340,34),new THREE.MeshStandardMaterial({color:'#44aab0',roughness:.24,metalness:.08}));water.rotation.x=-Math.PI/2;water.position.set(0,-.12,1);water.receiveShadow=true;scene.add(water);
 const water2=new THREE.Mesh(new THREE.PlaneGeometry(350,70),new THREE.MeshStandardMaterial({color:'#428f9b',roughness:.25}));water2.rotation.x=-Math.PI/2;water2.position.set(0,-.22,162);scene.add(water2);
 addBox(scene,[0,-.1,-17],[320,.18,2.8],M.sand,{cast:false});addBox(scene,[0,-.1,19],[320,.18,2.5],M.sand,{cast:false});
 // City avenues and local streets.
 for(const x of [-75,-45,-15,15,45,75])addBox(scene,[x,.005,-48],[7,.12,115],M.road,{cast:false});
 for(const z of [-96,-70,-44,-18])addBox(scene,[0,.008,z],[180,.12,6],M.road,{cast:false});
 for(const x of [-75,-45,-15,15,45,75])for(const z of [-96,-70,-44,-18]){for(let k=-2;k<=2;k++)addBox(scene,[x+k*1.1,.075,z],[.12,.025,1.3],M.roadLine,{cast:false})}
 // Long pale bridge, guard rails, supports and painted center stripe.
 addBox(scene,[0,.55,0],[11,1.1,42],mat('#b9b6a8'));addBox(scene,[0,1.14,0],[8.5,.12,42],M.road);
 for(const x of [-4.3,4.3]){addBox(scene,[x,1.7,0],[.22,.95,42],mat('#e7d8b8'));for(let z=-19;z<20;z+=3)addBox(scene,[x,1.3,z],[.22,.16,.28],mat('#edb979'))}
 for(let z=-19;z<=19;z+=5)addBox(scene,[0,1.22,z],[.12,.035,2.2],M.roadLine,{cast:false});
 for(const z of [-15,-7,7,15])for(const x of [-4,4])addBox(scene,[x,-2,z],[.8,5,.8],mat('#858b7d'));
 // A compact pastel city on the south shore.
 const lots=[[-60,-83,18,14,16],[-30,-83,18,14,23],[0,-83,18,14,29],[30,-83,18,14,17],[60,-83,18,14,25],[-60,-57,18,13,22],[-30,-57,18,13,14],[0,-57,18,13,19],[30,-57,18,13,30],[60,-57,18,13,17],[-60,-31,18,13,15],[-30,-31,18,13,26],[0,-31,18,13,17],[30,-31,18,13,22],[60,-31,18,13,14]];
 for(const [x,z,w,d,h] of lots)building(x+(rand()-.5)*2,z+(rand()-.5)*1.5,w,d,h,rand()>.76?1:0);
 // Waterfront promenade and cafe awnings.
 for(let x=-70;x<=70;x+=12){addCyl(scene,[x,0,-12.1],.12,.12,2.1,mat('#4b5150'),7);const lamp=new THREE.Mesh(new THREE.SphereGeometry(.22,8,7),mat('#fff0c7',.3,{emissive:'#ffbf70',emissiveIntensity:.3}));lamp.position.set(x,2.13,-12.1);scene.add(lamp)}
 // Streetside palms, park grass and swamp mangroves.
 for(const x of [-82,-64,-45,-26,-8,10,29,48,67,84]){palm(x,-10,rand()*.18+.82);palm(x,-105,rand()*.2+.85)}
 for(let x=-78;x<=78;x+=11){for(let z=28;z<145;z+=13){if(rand()>.15)palm(x+(rand()-.5)*5,z+(rand()-.5)*5,.72+rand()*.45,true)}}
 for(let i=0;i<33;i++){const x=(rand()-.5)*180,z=28+rand()*120;smallTree(x,z,.65+rand()*.6)}
 // Brush islands in the shallow wetlands.
 for(let i=0;i<42;i++){const x=(rand()-.5)*195,z=38+rand()*103;const b=new THREE.Mesh(new THREE.SphereGeometry(.55+rand()*.65,7,5),mat(rand()>.5?'#718b52':'#607e4d'));b.scale.set(1,.55,1);b.position.set(x,.22,z);scene.add(b)}
 for(const x of [-12,12])streetLight(x,-19);for(const x of [-45,45])streetLight(x,-45);
}
buildWorld();

// CHARACTER: stylized, articulated proportions rather than block geometry.
function makeLucia(){const g=new THREE.Group();const skin=mat('#c98762'),hair=mat('#3a2924'),shirt=mat('#48a875'),denim=mat('#4c91c5'),shoe=mat('#f1e3cc'),gold=mat('#e6b96f');
 const hips=addCyl(g,[0,1.02,0],.28,.31,.38,denim,12);hips.rotation.z=Math.PI/2;
 const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.29,.64,5,12),shirt);torso.position.y=1.63;torso.castShadow=true;g.add(torso);
 const neck=addCyl(g,[0,2.11,0],.11,.12,.19,skin,10);
 const head=new THREE.Mesh(new THREE.SphereGeometry(.245,16,13),skin);head.position.set(0,2.39,0);head.scale.set(.84,1.12,.92);head.castShadow=true;g.add(head);
 const haircap=new THREE.Mesh(new THREE.SphereGeometry(.255,14,9,0,Math.PI*2,0,Math.PI*.61),hair);haircap.position.set(0,2.46,-.005);haircap.scale.set(.93,1.1,.98);g.add(haircap);
 const pony=new THREE.Mesh(new THREE.CapsuleGeometry(.075,.35,4,8),hair);pony.position.set(-.18,2.2,-.12);pony.rotation.z=-.35;g.add(pony);
 // face features, delicate necklace, and shoulder straps
 for(const x of [-.09,.09]){const eye=new THREE.Mesh(new THREE.SphereGeometry(.024,7,6),mat('#282729'));eye.position.set(x,2.4,.205);g.add(eye)}
 addCyl(g,[0,1.95,.05],.29,.29,.035,gold,16);
 const arms=[],legs=[];for(const sign of [-1,1]){const arm=new THREE.Group();arm.position.set(sign*.34,1.86,0);const upper=new THREE.Mesh(new THREE.CapsuleGeometry(.095,.33,4,9),skin);upper.position.y=-.22;upper.rotation.z=sign*-.09;upper.castShadow=true;arm.add(upper);const hand=new THREE.Mesh(new THREE.SphereGeometry(.1,9,7),skin);hand.position.y=-.5;arm.add(hand);g.add(arm);arms.push(arm);
 const leg=new THREE.Group();leg.position.set(sign*.16,.92,0);const thigh=new THREE.Mesh(new THREE.CapsuleGeometry(.115,.36,4,9),denim);thigh.position.y=-.22;thigh.castShadow=true;leg.add(thigh);const calf=new THREE.Mesh(new THREE.CapsuleGeometry(.085,.42,4,9),skin);calf.position.y=-.62;calf.castShadow=true;leg.add(calf);const sneaker=new THREE.Mesh(new THREE.SphereGeometry(.12,9,7),shoe);sneaker.scale.set(1.25,.65,1.7);sneaker.position.set(0,-.91,.07);leg.add(sneaker);g.add(leg);legs.push(leg)}
 g.userData={arms,legs,head,torso};return g}
const player=makeLucia();player.position.set(-28,0,-36);scene.add(player);
const playerState={heading:0,velocity:0,onFoot:true,inVehicle:null,walking:0,health:100,flareAmmo:4};

