function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2700)}
const keys={};let started=false,paused=false,dragging=false,lastX=0,lastY=0,cameraYaw=0,cameraPitch=.2,elapsed=0;
function onKey(e,down){const k=e.key.toLowerCase();if(['w','a','s','d',' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys[k]=down;if(down&&!e.repeat){if(k==='e')interact();if(k==='f')useFlare();if(k==='escape'&&started){paused=!paused;document.querySelector('#pause-chip').classList.toggle('show',paused)}}}
addEventListener('keydown',e=>onKey(e,true));addEventListener('keyup',e=>onKey(e,false));
canvas.addEventListener('pointerdown',e=>{dragging=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture?.(e.pointerId)});canvas.addEventListener('pointerup',()=>dragging=false);canvas.addEventListener('pointercancel',()=>dragging=false);canvas.addEventListener('pointermove',e=>{if(!dragging||!started)return;cameraYaw-=(e.clientX-lastX)*.004;cameraPitch=THREE.MathUtils.clamp(cameraPitch+(e.clientY-lastY)*.003,-.05,.72);lastX=e.clientX;lastY=e.clientY});
for(const button of document.querySelectorAll('[data-key]')){const k=button.dataset.key;button.addEventListener('pointerdown',e=>{e.preventDefault();keys[k]=true});for(const ev of ['pointerup','pointercancel','pointerleave'])button.addEventListener(ev,()=>keys[k]=false)}
function interact(){if(!started)return;const pos=playerState.inVehicle?playerState.inVehicle.position:player.position;if(playerState.inVehicle){const v=playerState.inVehicle;playerState.inVehicle=null;playerState.onFoot=true;player.visible=true;player.position.copy(v.position);player.position.x+=2.6;player.position.y=0;document.querySelector('#vehicle-hud').classList.remove('active');toast('BACK ON FOOT');return}
 let nearest=null,best=5;for(const v of world.vehicles){if(v.userData.police)continue;const d=pos.distanceTo(v.position);if(d<best){best=d;nearest=v}}if(nearest){playerState.inVehicle=nearest;playerState.onFoot=false;player.visible=false;nearest.userData.speed=0;document.querySelector('#vehicle-hud').classList.add('active');toast(nearest.userData.type==='boat'?'BOAT READY · FOLLOW THE WATER':'COASTLINE GT · TAKE THE SCENIC ROUTE');return}toast('NOTHING CLOSE ENOUGH TO USE')}
function useFlare(){if(!started||playerState.flareAmmo<=0){if(playerState.flareAmmo<=0)toast('NO FLARES LEFT');return}playerState.flareAmmo--;document.querySelector('.weapon-card strong').textContent='SIGNAL FLARE';document.querySelector('.ammo').textContent=String(playerState.flareAmmo).padStart(2,'0');const p=new THREE.Mesh(new THREE.SphereGeometry(.11,8,7),new THREE.MeshBasicMaterial({color:'#ffad62'}));const light=new THREE.PointLight('#ff9048',2.2,12);p.add(light);const base=playerState.inVehicle||player;p.position.copy(base.position);p.position.y+=1.65;p.position.x+=Math.sin(playerState.heading)*.8;p.position.z+=Math.cos(playerState.heading)*.8;scene.add(p);world.projectiles.push({mesh:p,velocity:new THREE.Vector3(Math.sin(playerState.heading)*9,5,Math.cos(playerState.heading)*9),life:2.1});toast('SIGNAL FLARE · F');setTimeout(()=>{if(playerState.flareAmmo>=0)document.querySelector('.weapon-card strong').textContent='SIGNAL FLARE'},200)}
function missionUpdate(){const m=missions[missionIndex];const p=playerState.inVehicle?playerState.inVehicle.position:player.position;const d=p.distanceTo(m.point);document.querySelector('#mission-distance').textContent=d>1000?`${(d/1000).toFixed(1)} KM`:`${Math.round(d*10)} M`;if(d<5){if(missionIndex<missions.length-1){toast(m.reward);missionIndex++;setMission()}else if(!missionComplete){missionComplete=true;document.querySelector('#mission-title').innerHTML='County <em>complete</em>';document.querySelector('#mission-copy').textContent='The sunset is yours. Explore the city, bay, and wetlands.';document.querySelector('#mission-state').textContent='FREE ROAM';document.querySelector('#mission-progress').style.width='100%';markerGroup.visible=false;toast('STORY COMPLETE · FREE ROAM UNLOCKED')}}}
function updateWorld(dt){elapsed+=dt;const m=markerGroup.children;if(m.length){m[1].rotation.z+=dt*.42;m[2].position.y=5.1+Math.sin(elapsed*2.1)*.25;m[0].scale.y=1+.1*Math.sin(elapsed*2)}
 for(const n of world.npcs){n.userData.phase+=dt*.6;n.position.x=n.userData.originX+Math.sin(n.userData.phase)*.8;n.position.z=n.userData.originZ+Math.cos(n.userData.phase*.7)*.7}
 for(const q of world.projectiles){q.life-=dt;q.mesh.position.addScaledVector(q.velocity,dt);q.velocity.y-=9*dt;q.mesh.scale.setScalar(Math.max(.01,q.life/2));if(q.life<=0){scene.remove(q.mesh);world.projectiles.splice(world.projectiles.indexOf(q),1)}}
 for(const v of world.vehicles.filter(v=>v.userData.type==='boat')){if(!playerState.inVehicle||v!==playerState.inVehicle){v.position.y=.12+Math.sin(elapsed*1.7+v.position.x)*.08;v.rotation.z=Math.sin(elapsed*1.1+v.position.z)*.015}}
}
function updatePlayer(dt){const v=playerState.inVehicle;const forward=keys.w||keys.arrowup,back=keys.s||keys.arrowdown,left=keys.a||keys.arrowleft,right=keys.d||keys.arrowright;let move=0,strafe=0;
 if(v){const type=v.userData.type,acc=type==='boat'?12:16,max=type==='boat'?13:21;v.userData.speed+=(forward?acc:0)-(back?acc*.82:0);v.userData.speed*=Math.pow(.985,dt*60);v.userData.speed=THREE.MathUtils.clamp(v.userData.speed,-max*.48,max);if(left)v.rotation.y+=dt*(v.userData.speed>=0?1:-1)*1.5;if(right)v.rotation.y-=dt*(v.userData.speed>=0?1:-1)*1.5;v.position.x+=Math.sin(v.rotation.y)*v.userData.speed*dt;v.position.z+=Math.cos(v.rotation.y)*v.userData.speed*dt;if(type==='boat')v.position.y=.15+Math.sin(elapsed*2)*.07;playerState.heading=v.rotation.y;const mph=Math.abs(v.userData.speed)*3.1;document.querySelector('#speed').textContent=String(Math.round(mph)).padStart(2,'0');document.querySelector('#speed-bar').style.width=`${Math.min(100,mph/1.1)}%`;document.querySelector('#vehicle-hud>strong').textContent=type==='boat'?'BAY RUNNER':'COASTLINE GT';
 }else{move=(forward?1:0)-(back?1:0);strafe=(right?1:0)-(left?1:0);const speed=keys.shift?9:5.1;const fx=Math.sin(cameraYaw),fz=Math.cos(cameraYaw),rx=Math.cos(cameraYaw),rz=-Math.sin(cameraYaw);let dx=fx*move+rx*strafe,dz=fz*move+rz*strafe;const mag=Math.hypot(dx,dz);if(mag){dx/=mag;dz/=mag;player.position.x+=dx*speed*dt;player.position.z+=dz*speed*dt;playerState.heading=Math.atan2(dx,dz);player.rotation.y=playerState.heading;playerState.walking+=dt*speed*(keys.shift?1.5:1)}const {legs,arms}=player.userData;for(let i=0;i<2;i++){const phase=playerState.walking*(i?1:-1);legs[i].rotation.x=mag?Math.sin(phase)*.52:THREE.MathUtils.damp(legs[i].rotation.x,0,9,dt);arms[i].rotation.x=mag?Math.sin(phase+Math.PI)*.26:THREE.MathUtils.damp(arms[i].rotation.x,0,9,dt)}}
 player.position.x=THREE.MathUtils.clamp(player.position.x,-115,115);player.position.z=THREE.MathUtils.clamp(player.position.z,-115,145);
 // A soft camera follow, with a little extra lead when driving.
